<template><WorkspacePage title="登录日志" subtitle="查询登录记录并处理异常锁定"><a-form v-show="showSearch" class="query-form" layout="inline"><a-form-item label="登录地址"><a-input v-model:value="queryParams.ipaddr" allow-clear @press-enter="handleQuery" /></a-form-item><a-form-item label="用户名称"><a-input v-model:value="queryParams.userName" allow-clear @press-enter="handleQuery" /></a-form-item><a-form-item label="状态"><a-select v-model:value="queryParams.status" allow-clear :options="statusOptions" /></a-form-item><a-form-item label="登录时间"><a-range-picker v-model:value="dateRange" value-format="YYYY-MM-DD HH:mm:ss" show-time /></a-form-item><a-form-item><a-button type="primary" @click="handleQuery"><SearchOutlined />搜索</a-button><a-button @click="resetQuery"><ReloadOutlined />重置</a-button></a-form-item></a-form><div class="toolbar"><a-space><a-button danger :disabled="!ids.length" @click="handleDelete" v-hasPermi="['monitor:logininfor:remove']"><DeleteOutlined />删除</a-button><a-button danger @click="handleClean" v-hasPermi="['monitor:logininfor:remove']"><ClearOutlined />清空</a-button><a-button :disabled="ids.length!==1" @click="handleUnlock" v-hasPermi="['monitor:logininfor:unlock']"><UnlockOutlined />解锁</a-button><a-button @click="handleExport" v-hasPermi="['monitor:logininfor:export']"><DownloadOutlined />导出</a-button></a-space><a-button shape="circle" @click="showSearch=!showSearch"><FilterOutlined /></a-button></div><ResourceTable :columns="columns" :rows="logininforList" :loading="loading" :pagination="false" row-key="infoId" :scroll="{x:1100}" @change="handleTableChange"><template #headerCell="{column}"><a-checkbox v-if="column.key==='select'" :checked="allSelected" :indeterminate="ids.length>0&&!allSelected" @change="toggleAll" /></template><template #bodyCell="{column,record}"><template v-if="column.key==='select'"><a-checkbox :checked="ids.includes(record.infoId)" @change="e=>toggleRow(record,e.target.checked)" /></template><template v-else-if="column.key==='status'"><dict-tag :options="sys_common_status" :value="record.status" /></template><template v-else-if="column.key==='loginTime'">{{parseTime(record.loginTime)}}</template></template></ResourceTable><a-pagination v-if="total>0" v-model:current="queryParams.pageNum" v-model:page-size="queryParams.pageSize" :total="total" show-size-changer @change="getList" /></WorkspacePage></template>
<script setup name="Logininfor">
import{ClearOutlined,DeleteOutlined,DownloadOutlined,FilterOutlined,ReloadOutlined,SearchOutlined,UnlockOutlined}from'@ant-design/icons-vue';import WorkspacePage from '@/components/Antd/WorkspacePage.vue';import ResourceTable from '@/components/Antd/ResourceTable.vue';import feedback from '@/plugins/antdFeedback';import{list,delLogininfor,cleanLogininfor,unlockLogininfor}from'@/api/monitor/logininfor'
const{proxy}=getCurrentInstance();const{sys_common_status}=proxy.useDict('sys_common_status');const logininforList=ref([]),loading=ref(true),showSearch=ref(true),ids=ref([]),selectedNames=ref([]),total=ref(0),dateRange=ref([]);const queryParams=reactive({pageNum:1,pageSize:10,ipaddr:undefined,userName:undefined,status:undefined,orderByColumn:'loginTime',isAsc:'descending'});const statusOptions=computed(()=>sys_common_status.value.map(x=>({label:x.label,value:x.value})));const allSelected=computed(()=>logininforList.value.length>0&&logininforList.value.every(x=>ids.value.includes(x.infoId)));const columns=[{title:'',key:'select',width:48},{title:'访问编号',dataIndex:'infoId',key:'infoId'},{title:'用户名称',dataIndex:'userName',key:'userName',sorter:true},{title:'地址',dataIndex:'ipaddr',key:'ipaddr'},{title:'登录地点',dataIndex:'loginLocation',key:'loginLocation',mobileHidden:true},{title:'操作系统',dataIndex:'os',key:'os',mobileHidden:true},{title:'浏览器',dataIndex:'browser',key:'browser',mobileHidden:true},{title:'登录状态',key:'status'},{title:'描述',dataIndex:'msg',key:'msg',ellipsis:true},{title:'访问时间',key:'loginTime',dataIndex:'loginTime',width:180,sorter:true,defaultSortOrder:'descend'}]
async function getList(){loading.value=true;try{const r=await list(proxy.addDateRange({...queryParams},dateRange.value));logininforList.value=r.rows;total.value=r.total;ids.value=[];selectedNames.value=[]}finally{loading.value=false}}function handleQuery(){queryParams.pageNum=1;getList()}function resetQuery(){dateRange.value=[];Object.assign(queryParams,{pageNum:1,ipaddr:undefined,userName:undefined,status:undefined,orderByColumn:'loginTime',isAsc:'descending'});getList()}function toggleRow(row,on){ids.value=on?[...new Set([...ids.value,row.infoId])]:ids.value.filter(x=>x!==row.infoId);selectedNames.value=logininforList.value.filter(x=>ids.value.includes(x.infoId)).map(x=>x.userName)}function toggleAll(e){ids.value=e.target.checked?logininforList.value.map(x=>x.infoId):[];selectedNames.value=e.target.checked?logininforList.value.map(x=>x.userName):[]}function handleTableChange(_,__,s){if(!s.field)return;queryParams.orderByColumn=s.field;queryParams.isAsc=s.order==='ascend'?'ascending':'descending';getList()}async function handleDelete(row={}){try{const values=row.infoId||ids.value;await feedback.confirm(`是否确认删除访问编号为"${values}"的数据项?`);await delLogininfor(values);feedback.msgSuccess('删除成功');getList()}catch{}}async function handleClean(){try{await feedback.confirm('是否确认清空所有登录日志数据项?');await cleanLogininfor();feedback.msgSuccess('清空成功');getList()}catch{}}async function handleUnlock(){try{const name=selectedNames.value;await feedback.confirm(`是否确认解锁用户"${name}"数据项?`);await unlockLogininfor(name);feedback.msgSuccess(`用户${name}解锁成功`)}catch{}}function handleExport(){proxy.download('monitor/logininfor/export',{...queryParams},`logininfor_${Date.now()}.xlsx`)}getList()
</script><style scoped>.query-form{padding:16px;margin-bottom:12px;border:1px solid var(--workspace-border)}.toolbar{display:flex;justify-content:space-between;margin-bottom:12px}:deep(.ant-pagination){justify-content:flex-end;margin-top:14px}</style>
